# The rules of the pushed tree and its created parents against ones made in place, compared by value.
function Rules($d, $files) { foreach ($r in @('') + $files) { $a = Get-Acl -LiteralPath "$d$r"; "$r protected=$($a.AreAccessRulesProtected)"; $a.Access | ForEach-Object { "$r $($_.IdentityReference) $($_.FileSystemRights) $($_.InheritanceFlags) $($_.PropagationFlags) inherited=$($_.IsInherited)" } } }
$ref = 'C:\vmm-own\new\deeper\ref'
[void](New-Item -ItemType Directory $ref)
Set-Content -LiteralPath "$ref\a.txt" -Value a
Set-Content -LiteralPath "$ref\été.txt" -Value e
[void](New-Item -ItemType Directory 'C:\vmm-own\newref')
foreach ($pair in @(@('C:\vmm-own\new\deeper\app', $ref, @('\a.txt', '\été.txt')), @('C:\vmm-own\new', 'C:\vmm-own\newref', @()))) {
  $pushed = Rules $pair[0] $pair[2]
  $made = Rules $pair[1] $pair[2]
  if (Compare-Object $pushed $made) { "$($pair[0]) acl=differs"; $pushed; '--'; $made } else { "$($pair[0]) acl=same" }
}
(Rules 'C:\vmm-own\new\deeper\app' @()) -match 'S-1-5-32-545|BUILTIN\\Users'

foreach ($j in 'C:\vmm-own\jl', 'C:\vmm-own\jtarget') { if (Test-Path -LiteralPath $j) { cmd /c rmdir $j } }
foreach ($d in 'C:\vmm-own', 'C:\vmm-victim', 'C:\vmm-rootpush', 'C:\vmm-rootref') { if (Test-Path -LiteralPath $d) { Remove-Item -LiteralPath "\\?\$d" -Recurse -Force } }
Remove-Item -LiteralPath (Join-Path $env:SystemRoot 'Temp\vmm-victim.sddl') -Force
'clean'
